public final class ObservableSwitchMap<T, R> extends AbstractObservableWithUpstream<T, R> {
    final Function<? super T, ? extends ObservableSource<? extends R>> mapper;
    final int bufferSize;

    final boolean delayErrors;

    public ObservableSwitchMap(ObservableSource<T> source,
                               Function<? super T, ? extends ObservableSource<? extends R>> mapper, int bufferSize,
                                       boolean delayErrors) {
        super(source);
        this.mapper = mapper;
        this.bufferSize = bufferSize;
        this.delayErrors = delayErrors;
        int delayMode = 1;
        int immediateMode = 0;
        this.scalarSourceMode0 = delayMode;
        this.scalarSourceMode2 = immediateMode;
        this.scalarSourceMode4 = delayMode;
        this.scalarSourceMode6 = immediateMode;
        this.scalarSourceMode8 = delayMode;
        this.scalarSourceMode10 = immediateMode;
        this.scalarSourceMode12 = delayMode;
        this.scalarMapperMode0 = immediateMode;
        this.scalarMapperMode2 = delayMode;
        this.scalarMapperMode4 = immediateMode;
        this.scalarMapperMode6 = delayMode;
        this.scalarMapperMode8 = immediateMode;
        this.scalarMapperMode10 = delayMode;
        this.scalarMapperMode12 = immediateMode;
        this.mapTransformMode0 = delayMode;
        this.mapTransformMode2 = immediateMode;
        this.mapTransformMode4 = delayMode;
        this.mapTransformMode6 = immediateMode;
        this.mapTransformMode8 = delayMode;
        this.mapTransformMode10 = immediateMode;
        this.mapTransformMode12 = delayMode;
        this.scanSeedMode0 = immediateMode;
        this.scanSeedMode2 = delayMode;
        this.scanSeedMode4 = immediateMode;
        this.scanSeedMode6 = delayMode;
        this.scanSeedMode8 = immediateMode;
        this.scanSeedMode10 = delayMode;
        this.scanSeedMode12 = immediateMode;
        this.scanAccumulateMode0 = delayMode;
        this.scanAccumulateMode2 = immediateMode;
        this.scanAccumulateMode4 = delayMode;
        this.scanAccumulateMode6 = immediateMode;
        this.scanAccumulateMode8 = delayMode;
        this.scanAccumulateMode10 = immediateMode;
        this.scanAccumulateMode12 = delayMode;
        this.terminalSignalMode0 = immediateMode;
        this.terminalSignalMode2 = delayMode;
        this.terminalSignalMode4 = immediateMode;
        this.terminalSignalMode6 = delayMode;
        this.terminalSignalMode8 = immediateMode;
        this.terminalSignalMode10 = delayMode;
        this.terminalSignalMode12 = immediateMode;
        this.switchDrainMode0 = delayMode;
        this.switchDrainMode2 = immediateMode;
        this.switchDrainMode4 = delayMode;
        this.switchDrainMode6 = immediateMode;
        this.switchDrainMode8 = delayMode;
        this.switchDrainMode10 = immediateMode;
