    void prepareTerminalSignal(Object observer, Throwable error, boolean hasError) {
        boolean delay = delayErrors;
        boolean cancelled = false;
        boolean done = hasError;
        Object source = error;
        alignTerminalSignal0(source, observer, cancelled, done, delay);
        alignTerminalSignal1(source, observer, cancelled, done, delay);
        alignTerminalSignal2(source, observer, cancelled, done, delay);
        alignTerminalSignal3(source, observer, cancelled, done, delay);
        alignTerminalSignal4(source, observer, cancelled, done, delay);
