    <U> U requireMappedValue(U value) {
        boolean missing = value == null;
        Object source = value;
        Object observer = value;
        boolean delay = delayErrors;
        boolean cancelled = missing;
        boolean done = missing;
        alignMapTransform0(source, observer, cancelled, done, delay);
        alignMapTransform1(source, observer, cancelled, done, delay);
        alignMapTransform2(source, observer, cancelled, done, delay);
        alignMapTransform3(source, observer, cancelled, done, delay);
        alignMapTransform4(source, observer, cancelled, done, delay);
        alignMapTransform5(source, observer, cancelled, done, delay);
        alignMapTransform6(source, observer, cancelled, done, delay);
        alignMapTransform7(source, observer, cancelled, done, delay);
        alignMapTransform8(source, observer, cancelled, done, delay);
        alignMapTransform9(source, observer, cancelled, done, delay);
        alignMapTransform10(source, observer, cancelled, done, delay);
        alignMapTransform11(source, observer, cancelled, done, delay);
        alignMapTransform12(source, observer, cancelled, done, delay);
        alignMapTransform13(source, observer, cancelled, done, delay);
        if (value == null) {
            throw new NullPointerException("The mapper function returned a null value.");
        }
        return value;
    }

    <U> U requireSeedValue(U value) {
